void matmul(float* xout, float* x, float* w, int n, int d) {
    dispatch_apply((size_t)d, DISPATCH_APPLY_AUTO, ^(size_t i) {
        const float* wp = w + i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j + 16 <= n; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    });
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

typedef struct {
    float*       xout;
    const float* x;
    const float* w;
    int          n;
    int          d;
} mm_task_t;

static inline float mm_dot_neon(const float* restrict wp,
                                const float* restrict xp,
                                int n)
{
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);

    const int nb = n & ~15;
    int j = 0;
    for (; j < nb; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(xp + j));
        a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(xp + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(xp + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(xp + j + 12));
    }

    float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float val = vaddvq_f32(s);

    for (; j < n; ++j) val += wp[j] * xp[j];
    return val;
}

#define MM_ROWS_PER_TASK 8

static void mm_run(void* ctxp, size_t t)
{
    const mm_task_t* c = (const mm_task_t*)ctxp;
    int start = (int)(t * MM_ROWS_PER_TASK);
    int end   = start + MM_ROWS_PER_TASK;
    if (end > c->d) end = c->d;

    const float* xp = c->x;
    const int    n  = c->n;

    for (int i = start; i < end; ++i) {
        c->xout[i] = mm_dot_neon(c->w + (size_t)i * (size_t)n, xp, n);
    }
}

void matmul(float* xout, float* x, float* w, int n, int d)
{
    if (d <= 0) return;

    mm_task_t c = { xout, x, w, n, d };
    size_t ntasks = (size_t)((d + MM_ROWS_PER_TASK - 1) / MM_ROWS_PER_TASK);

    dispatch_apply_f(ntasks, DISPATCH_APPLY_AUTO, &c, mm_run);
}

#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    // W (d,n) @ x (n,) -> xout (d,)
    const int n4 = n & ~15;   // multiple of 16

    #pragma omp parallel for
    for (int i = 0; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n4; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
        }
        // tail (n multiple of 4 in practice, but handle any)
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <stdint.h>
#include <string.h>

// Process multiple rows at once so each chunk of x stays in registers/cache.
void matmul(float* xout, float* x, float* w, int n, int d) {
    // W (d,n) @ x (n,) -> xout (d,)
    int i = 0;
    const int R = 4; // rows processed together

    for (; i + R <= d; i += R) {
        float32x4_t acc0 = vdupq_n_f32(0.0f);
        float32x4_t acc1 = vdupq_n_f32(0.0f);
        float32x4_t acc2 = vdupq_n_f32(0.0f);
        float32x4_t acc3 = vdupq_n_f32(0.0f);

        const float* w0 = w + (size_t)i * n;
        const float* w1 = w0 + n;
        const float* w2 = w1 + n;
        const float* w3 = w2 + n;

        int j = 0;
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            acc0 = vfmaq_f32(acc0, vld1q_f32(w0 + j), xv);
            acc1 = vfmaq_f32(acc1, vld1q_f32(w1 + j), xv);
            acc2 = vfmaq_f32(acc2, vld1q_f32(w2 + j), xv);
            acc3 = vfmaq_f32(acc3, vld1q_f32(w3 + j), xv);
        }
        float s0 = vaddvq_f32(acc0);
        float s1 = vaddvq_f32(acc1);
        float s2 = vaddvq_f32(acc2);
        float s3 = vaddvq_f32(acc3);
        for (; j < n; j++) {
            float xj = x[j];
            s0 += w0[j] * xj;
            s1 += w1[j] * xj;
            s2 += w2[j] * xj;
            s3 += w3[j] * xj;
        }
        xout[i + 0] = s0;
        xout[i + 1] = s1;
        xout[i + 2] = s2;
        xout[i + 3] = s3;
    }

    for (; i < d; i++) {
        const float* wi = w + (size_t)i * n;
        float32x4_t acc = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j + 4 <= n; j += 4) {
            acc = vfmaq_f32(acc, vld1q_f32(wi + j), vld1q_f32(x + j));
        }
        float s = vaddvq_f32(acc);
        for (; j < n; j++) s += wi[j] * x[j];
        xout[i] = s;
    }
}

