typedef struct {
    float* xout;
    float* x;
    float* w;
    int n;
    int n4;
    int d;
} mm_args;

static void matmul_chunk(void* ctx, size_t idx) {
    mm_args* a = (mm_args*)ctx;
    // Process 4 rows per idx (4-row blocking) to amortize dispatch overhead.
    int i0 = (int)idx * 4;
    int i1 = i0 + 4;
    if (i1 > a->d) i1 = a->d;

    const float* x = a->x;
    const int n = a->n;
    const int n4 = a->n4;

    for (int i = i0; i < i1; i++) {
        const float* wp = a->w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n4; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        a->xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    const int n4 = n & ~15;
    mm_args a = { xout, x, w, n, n4, d };

    int nchunks = (d + 3) / 4;
    if (nchunks < 1) nchunks = 1;

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t i) {
        matmul_chunk(&a, i);
    });
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

// Compute one output row: xout[i] = dot(w_row, x)
static inline float matmul_row(const float* restrict wp, const float* restrict x, int n) {
    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);

    const int n16 = n & ~15;
    int j = 0;
    for (; j < n16; j += 16) {
        float32x4_t x0 = vld1q_f32(x + j);
        float32x4_t x1 = vld1q_f32(x + j + 4);
        float32x4_t x2 = vld1q_f32(x + j + 8);
        float32x4_t x3 = vld1q_f32(x + j + 12);
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
        a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
        a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
        a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
    }
    for (; j + 4 <= n; j += 4) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
    }
    float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float val = vaddvq_f32(s);
    for (; j < n; j++) {
        val += wp[j] * x[j];
    }
    return val;
}

typedef struct {
    float* xout;
    const float* x;
    const float* w;
    int n;
    int d;
} mm_ctx;

static void matmul_chunk(void* ctxp, size_t start, size_t end) {
    mm_ctx* c = (mm_ctx*)ctxp;
    const int n = c->n;
    const float* x = c->x;
    const float* w = c->w;
    float* xout = c->xout;
    for (size_t i = start; i < end; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        xout[i] = matmul_row(wp, x, n);
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    mm_ctx c;
    c.xout = xout;
    c.x = x;
    c.w = w;
    c.n = n;
    c.d = d;

    if (d < 256) {
        // Small: serial to avoid dispatch overhead.
        for (int i = 0; i < d; i++) {
            xout[i] = matmul_row(w + (size_t)i * (size_t)n, x, n);
        }
        return;
    }

    dispatch_apply(d, DISPATCH_APPLY_AUTO, ^(size_t i) {
        const float* wp = w + (size_t)i * (size_t)n;
        xout[i] = matmul_row(wp, x, n);
    });
}

#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    const int n4 = n & ~15;   // multiple of 16
    const int d2 = d & ~1;    // even part

    #pragma omp parallel for
    for (int i = 0; i < d2; i += 2) {
        const float* wp0 = w + (size_t)i * (size_t)n;
        const float* wp1 = wp0 + n;

        float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
        float32x4_t b0 = vdupq_n_f32(0.0f), b1 = vdupq_n_f32(0.0f);
        float32x4_t b2 = vdupq_n_f32(0.0f), b3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n4; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);

            a0 = vfmaq_f32(a0, vld1q_f32(wp0 + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp0 + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp0 + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp0 + j + 12), x3);

            b0 = vfmaq_f32(b0, vld1q_f32(wp1 + j),      x0);
            b1 = vfmaq_f32(b1, vld1q_f32(wp1 + j + 4),  x1);
            b2 = vfmaq_f32(b2, vld1q_f32(wp1 + j + 8),  x2);
            b3 = vfmaq_f32(b3, vld1q_f32(wp1 + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            a0 = vfmaq_f32(a0, vld1q_f32(wp0 + j), xv);
            b0 = vfmaq_f32(b0, vld1q_f32(wp1 + j), xv);
        }
        float32x4_t sa = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float32x4_t sb = vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3));
        float va = vaddvq_f32(sa);
        float vb = vaddvq_f32(sb);
        for (; j < n; j++) {
            va += wp0[j] * x[j];
            vb += wp1[j] * x[j];
        }
        xout[i]     = va;
        xout[i + 1] = vb;
    }

    // odd row tail
    if (d & 1) {
        int i = d - 1;
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n4; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4)
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    // W (d,n) @ x (n,) -> xout (d,)
    // 4 independent NEON FMA accumulators per row to break the FP dependency chain.
    const int n16 = n & ~15;   // multiple of 16

    #pragma omp parallel for schedule(static)
    for (int i = 0; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
        }
        // tail: n is a multiple of 4 in practice, but handle any
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    // W (d,n) @ x (n,) -> xout (d,)
    const int n16 = n & ~15;   // multiple of 16
    const int n4  = n & ~3;    // multiple of 4
    const int nb  = d >> 2;    // 4-row blocks

    // ---- main path: 4 rows per iteration, x reused across rows ----
    #pragma omp parallel for
    for (int b = 0; b < nb; b++) {
        const int i = b << 2;
        const float* wp0 = w + (size_t)i * (size_t)n;
        const float* wp1 = wp0 + n;
        const float* wp2 = wp1 + n;
        const float* wp3 = wp2 + n;

        float32x4_t a00 = vdupq_n_f32(0.f), a01 = a00, a02 = a00, a03 = a00;
        float32x4_t a10 = a00, a11 = a00, a12 = a00, a13 = a00;
        float32x4_t a20 = a00, a21 = a00, a22 = a00, a23 = a00;
        float32x4_t a30 = a00, a31 = a00, a32 = a00, a33 = a00;

        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a00 = vfmaq_f32(a00, vld1q_f32(wp0 + j),      x0);
            a01 = vfmaq_f32(a01, vld1q_f32(wp0 + j + 4),  x1);
            a02 = vfmaq_f32(a02, vld1q_f32(wp0 + j + 8),  x2);
            a03 = vfmaq_f32(a03, vld1q_f32(wp0 + j + 12), x3);
            a10 = vfmaq_f32(a10, vld1q_f32(wp1 + j),      x0);
            a11 = vfmaq_f32(a11, vld1q_f32(wp1 + j + 4),  x1);
            a12 = vfmaq_f32(a12, vld1q_f32(wp1 + j + 8),  x2);
            a13 = vfmaq_f32(a13, vld1q_f32(wp1 + j + 12), x3);
            a20 = vfmaq_f32(a20, vld1q_f32(wp2 + j),      x0);
            a21 = vfmaq_f32(a21, vld1q_f32(wp2 + j + 4),  x1);
            a22 = vfmaq_f32(a22, vld1q_f32(wp2 + j + 8),  x2);
            a23 = vfmaq_f32(a23, vld1q_f32(wp2 + j + 12), x3);
            a30 = vfmaq_f32(a30, vld1q_f32(wp3 + j),      x0);
            a31 = vfmaq_f32(a31, vld1q_f32(wp3 + j + 4),  x1);
            a32 = vfmaq_f32(a32, vld1q_f32(wp3 + j + 8),  x2);
            a33 = vfmaq_f32(a33, vld1q_f32(wp3 + j + 12), x3);
        }
        for (; j < n4; j += 4) {
            float32x4_t x0 = vld1q_f32(x + j);
            a00 = vfmaq_f32(a00, vld1q_f32(wp0 + j), x0);
            a10 = vfmaq_f32(a10, vld1q_f32(wp1 + j), x0);
            a20 = vfmaq_f32(a20, vld1q_f32(wp2 + j), x0);
            a30 = vfmaq_f32(a30, vld1q_f32(wp3 + j), x0);
        }
        float s0 = vaddvq_f32(vaddq_f32(vaddq_f32(a00, a01), vaddq_f32(a02, a03)));
        float s1 = vaddvq_f32(vaddq_f32(vaddq_f32(a10, a11), vaddq_f32(a12, a13)));
        float s2 = vaddvq_f32(vaddq_f32(vaddq_f32(a20, a21), vaddq_f32(a22, a23)));
        float s3 = vaddvq_f32(vaddq_f32(vaddq_f32(a30, a31), vaddq_f32(a32, a33)));
        for (; j < n; j++) {
            s0 += wp0[j] * x[j];
            s1 += wp1[j] * x[j];
            s2 += wp2[j] * x[j];
            s3 += wp3[j] * x[j];
        }
        xout[i]     = s0;
        xout[i + 1] = s1;
        xout[i + 2] = s2;
        xout[i + 3] = s3;
    }

    // ---- remainder rows (d % 4) ----
    for (int i = nb << 2; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.f), a1 = a0, a2 = a0, a3 = a0;
        int j = 0;
        for (; j < n16; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j < n4; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float val = vaddvq_f32(vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3)));
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

