static inline void matmul_rows(float* xout, const float* x, const float* w,
                               int n, int d, int i0, int i1) {
    const int n4 = n & ~15;   // multiple of 16
    for (int i = i0; i < i1; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n4; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;

    // Small problems: avoid dispatch overhead, run single-threaded.
    if ((long long)d * n < 16384) {
        matmul_rows(xout, x, w, n, d, 0, d);
        return;
    }

    dispatch_apply(d, DISPATCH_APPLY_AUTO, ^(size_t i) {
        matmul_rows(xout, x, w, n, d, (int)i, (int)i + 1);
    });
}

