// Process rows [i0, i1) of W (d,n) @ x (n,). Two-row blocking reuses x loads.
static void mm_block(float* xout, const float* x, const float* w, int n, int i0, int i1) {
    const int n16 = n & ~15;
    int i = i0;

    // ---- 2 rows at a time ----
    for (; i + 1 < i1; i += 2) {
        const float* wp0 = w + (size_t)i * (size_t)n;
        const float* wp1 = wp0 + n;

        float32x4_t a0 = vdupq_n_f32(0.f), a1 = vdupq_n_f32(0.f);
        float32x4_t a2 = vdupq_n_f32(0.f), a3 = vdupq_n_f32(0.f);
        float32x4_t b0 = vdupq_n_f32(0.f), b1 = vdupq_n_f32(0.f);
        float32x4_t b2 = vdupq_n_f32(0.f), b3 = vdupq_n_f32(0.f);

        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);

            a0 = vfmaq_f32(a0, vld1q_f32(wp0 + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp0 + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp0 + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp0 + j + 12), x3);

            b0 = vfmaq_f32(b0, vld1q_f32(wp1 + j),      x0);
            b1 = vfmaq_f32(b1, vld1q_f32(wp1 + j + 4),  x1);
            b2 = vfmaq_f32(b2, vld1q_f32(wp1 + j + 8),  x2);
            b3 = vfmaq_f32(b3, vld1q_f32(wp1 + j + 12), x3);
        }
        float32x4_t s0 = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float32x4_t s1 = vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3));
        float v0 = vaddvq_f32(s0);
        float v1 = vaddvq_f32(s1);

        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            v0 += vaddvq_f32(vmulq_f32(vld1q_f32(wp0 + j), xv));
            v1 += vaddvq_f32(vmulq_f32(vld1q_f32(wp1 + j), xv));
        }
        for (; j < n; j++) { v0 += wp0[j] * x[j]; v1 += wp1[j] * x[j]; }
        xout[i]     = v0;
        xout[i + 1] = v1;
    }

    // ---- leftover single row ----
    for (; i < i1; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.f), a1 = vdupq_n_f32(0.f);
        float32x4_t a2 = vdupq_n_f32(0.f), a3 = vdupq_n_f32(0.f);
        int j = 0;
        for (; j < n16; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j + 4 <= n; j += 4)
            val += vaddvq_f32(vmulq_f32(vld1q_f32(wp + j), vld1q_f32(x + j)));
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    // Small d: no dispatch overhead.
    if (d < 256) {
        mm_block(xout, x, w, n, 0, d);
        return;
    }

    // ~64-row chunks => plenty of work units for the 12-core scheduler.
    int chunk = (d + 63) / 64;
    if (chunk < 1) chunk = 1;
    int nchunks = (d + chunk - 1) / chunk;

    dispatch_apply((size_t)nchunks,
                   dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
                   ^(size_t b) {
        int i0 = (int)b * chunk;
        int i1 = i0 + chunk;
        if (i1 > d) i1 = d;
        mm_block(xout, x, w, n, i0, i1);
    });
}

