#include <stdint.h>

// Process 4 rows at a time so each chunk of x is loaded once and reused
// across 4 weight rows, improving L1/L2 reuse and arithmetic intensity.
void matmul(float* xout, float* x, float* w, int n, int d) {
    const int n4 = n & ~15;   // multiple of 16

    int i = 0;
    for (; i + 4 <= d; i += 4) {
        const float* w0 = w + (size_t)(i + 0) * (size_t)n;
        const float* w1 = w + (size_t)(i + 1) * (size_t)n;
        const float* w2 = w + (size_t)(i + 2) * (size_t)n;
        const float* w3 = w + (size_t)(i + 3) * (size_t)n;

        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        float32x4_t b0 = vdupq_n_f32(0.0f);
        float32x4_t b1 = vdupq_n_f32(0.0f);
        float32x4_t b2 = vdupq_n_f32(0.0f);
        float32x4_t b3 = vdupq_n_f32(0.0f);
        float32x4_t c0 = vdupq_n_f32(0.0f);
        float32x4_t c1 = vdupq_n_f32(0.0f);
        float32x4_t c2 = vdupq_n_f32(0.0f);
        float32x4_t c3 = vdupq_n_f32(0.0f);
        float32x4_t e0 = vdupq_n_f32(0.0f);
        float32x4_t e1 = vdupq_n_f32(0.0f);
        float32x4_t e2 = vdupq_n_f32(0.0f);
        float32x4_t e3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n4; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);

            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);

            b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
            b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
            b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
            b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);

            c0 = vfmaq_f32(c0, vld1q_f32(w2 + j),      x0);
            c1 = vfmaq_f32(c1, vld1q_f32(w2 + j + 4),  x1);
            c2 = vfmaq_f32(c2, vld1q_f32(w2 + j + 8),  x2);
            c3 = vfmaq_f32(c3, vld1q_f32(w2 + j + 12), x3);

            e0 = vfmaq_f32(e0, vld1q_f32(w3 + j),      x0);
            e1 = vfmaq_f32(e1, vld1q_f32(w3 + j + 4),  x1);
            e2 = vfmaq_f32(e2, vld1q_f32(w3 + j + 8),  x2);
            e3 = vfmaq_f32(e3, vld1q_f32(w3 + j + 12), x3);
        }

        float s0 = vaddvq_f32(vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3)));
        float s1 = vaddvq_f32(vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3)));
        float s2 = vaddvq_f32(vaddq_f32(vaddq_f32(c0, c1), vaddq_f32(c2, c3)));
        float s3 = vaddvq_f32(vaddq_f32(vaddq_f32(e0, e1), vaddq_f32(e2, e3)));

        // tail (n multiple of 4 in practice, but handle any)
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            s0 += vaddvq_f32(vmulq_f32(vld1q_f32(w0 + j), xv));
            s1 += vaddvq_f32(vmulq_f32(vld1q_f32(w1 + j), xv));
            s2 += vaddvq_f32(vmulq_f32(vld1q_f32(w2 + j), xv));
            s3 += vaddvq_f32(vmulq_f32(vld1q_f32(w3 + j), xv));
        }
        for (; j < n; j++) {
            float xv = x[j];
            s0 += w0[j] * xv;
            s1 += w1[j] * xv;
            s2 += w2[j] * xv;
            s3 += w3[j] * xv;
        }
        xout[i + 0] = s0;
        xout[i + 1] = s1;
        xout[i + 2] = s2;
        xout[i + 3] = s3;
    }

    // remaining rows
    for (; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n4; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        float val = vaddvq_f32(vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3)));
        for (; j + 4 <= n; j += 4) {
            val += vaddvq_f32(vmulq_f32(vld1q_f32(wp + j), vld1q_f32(x + j)));
        }
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <dispatch/dispatch.h>
#include <stdint.h>

typedef struct {
    float* xout;
    float* x;
    float* w;
    int n;
    int d;
} mm_args;

static void mm_rows(void* ctx, size_t i) {
    mm_args* a = (mm_args*)ctx;
    const int n = a->n;
    const float* x = a->x;
    const float* wp = a->w + (size_t)i * (size_t)n;
    const int n16 = n & ~15;

    float32x4_t a0 = vdupq_n_f32(0.0f);
    float32x4_t a1 = vdupq_n_f32(0.0f);
    float32x4_t a2 = vdupq_n_f32(0.0f);
    float32x4_t a3 = vdupq_n_f32(0.0f);

    int j = 0;
    for (; j < n16; j += 16) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
        a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
        a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
        a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
    }
    for (; j + 4 <= n; j += 4) {
        a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
    }
    float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
    float val = vaddvq_f32(s);
    for (; j < n; j++) val += wp[j] * x[j];
    a->xout[i] = val;
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    mm_args a = { xout, x, w, n, d };
    dispatch_apply((size_t)d, DISPATCH_APPLY_AUTO, ^(size_t i) {
        mm_rows(&a, i);
    });
}

#include <arm_neon.h>
#include <stdint.h>
#include <string.h>

// Chunked row-parallel matmul using dispatch_apply_f for real multi-core
// execution (omp pragma may be ignored under clang without -fopenmp).
// Each chunk handles a contiguous band of rows; within a row we use 4
// independent float32x4 accumulators over a 16-wide unroll for ILP.

typedef struct {
    float* xout;
    const float* x;
    const float* w;
    int n;
    int d;
    int rows_per_chunk;
} mm_ctx;

static void matmul_chunk(void* ctx_, size_t chunk_idx) {
    const mm_ctx* ctx = (const mm_ctx*)ctx_;
    const int n = ctx->n;
    const int d = ctx->d;
    const float* x = ctx->x;
    const float* w = ctx->w;
    float* xout = ctx->xout;

    int i0 = (int)chunk_idx * ctx->rows_per_chunk;
    int i1 = i0 + ctx->rows_per_chunk;
    if (i1 > d) i1 = d;

    const int n16 = n & ~15;

    for (int i = i0; i < i1; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);

        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) {
            val += wp[j] * x[j];
        }
        xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;

    // Choose chunk size ~ rows-per-core for load balance. 8 rows per chunk
    // worked well in prior attempts; scale up a bit for larger d.
    int rows_per_chunk = 8;
    if (d >= 512) rows_per_chunk = 16;
    if (d >= 2048) rows_per_chunk = 32;

    int nchunks = (d + rows_per_chunk - 1) / rows_per_chunk;

    mm_ctx ctx;
    ctx.xout = xout;
    ctx.x = x;
    ctx.w = w;
    ctx.n = n;
    ctx.d = d;
    ctx.rows_per_chunk = rows_per_chunk;

    dispatch_apply_f((size_t)nchunks,
                     dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
                     &ctx, matmul_chunk);
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

typedef struct { float* xout; float* x; float* w; int n; int d; int start; int end; } mm_arg;

static inline void mm_block(float* xout, float* x, float* w, int n, int d, int start, int end) {
    const int n16 = n & ~15;
    for (int i = start; i < end; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f);
        float32x4_t a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f);
        float32x4_t a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n16; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    // Chunk rows so each task does a decent amount of work, but enough tasks for 12 cores.
    int chunk = 16;
    while (chunk < d && (d + chunk - 1) / chunk > 96) chunk *= 2;
    int nchunks = (d + chunk - 1) / chunk;

    mm_arg args[128];
    if (nchunks > 128) nchunks = 128;

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t k) {
        int start = (int)k * chunk;
        int end = start + chunk;
        if (end > d) end = d;
        if (start < d) mm_block(xout, x, w, n, d, start, end);
    });
}

#include <arm_neon.h>
#include <stdint.h>

void matmul(float* xout, float* x, float* w, int n, int d) {
    const int n16 = n & ~15;
    const int d4  = d & ~3;

    #pragma omp parallel for
    for (int i = 0; i < d4; i += 4) {
        const float* w0 = w + (size_t)(i + 0) * (size_t)n;
        const float* w1 = w + (size_t)(i + 1) * (size_t)n;
        const float* w2 = w + (size_t)(i + 2) * (size_t)n;
        const float* w3 = w + (size_t)(i + 3) * (size_t)n;

        float32x4_t a00 = vdupq_n_f32(0.f), a01 = vdupq_n_f32(0.f);
        float32x4_t a02 = vdupq_n_f32(0.f), a03 = vdupq_n_f32(0.f);
        float32x4_t a10 = vdupq_n_f32(0.f), a11 = vdupq_n_f32(0.f);
        float32x4_t a12 = vdupq_n_f32(0.f), a13 = vdupq_n_f32(0.f);
        float32x4_t a20 = vdupq_n_f32(0.f), a21 = vdupq_n_f32(0.f);
        float32x4_t a22 = vdupq_n_f32(0.f), a23 = vdupq_n_f32(0.f);
        float32x4_t a30 = vdupq_n_f32(0.f), a31 = vdupq_n_f32(0.f);
        float32x4_t a32 = vdupq_n_f32(0.f), a33 = vdupq_n_f32(0.f);

        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);

            a00 = vfmaq_f32(a00, vld1q_f32(w0 + j),      x0);
            a01 = vfmaq_f32(a01, vld1q_f32(w0 + j + 4),  x1);
            a02 = vfmaq_f32(a02, vld1q_f32(w0 + j + 8),  x2);
            a03 = vfmaq_f32(a03, vld1q_f32(w0 + j + 12), x3);

            a10 = vfmaq_f32(a10, vld1q_f32(w1 + j),      x0);
            a11 = vfmaq_f32(a11, vld1q_f32(w1 + j + 4),  x1);
            a12 = vfmaq_f32(a12, vld1q_f32(w1 + j + 8),  x2);
            a13 = vfmaq_f32(a13, vld1q_f32(w1 + j + 12), x3);

            a20 = vfmaq_f32(a20, vld1q_f32(w2 + j),      x0);
            a21 = vfmaq_f32(a21, vld1q_f32(w2 + j + 4),  x1);
            a22 = vfmaq_f32(a22, vld1q_f32(w2 + j + 8),  x2);
            a23 = vfmaq_f32(a23, vld1q_f32(w2 + j + 12), x3);

            a30 = vfmaq_f32(a30, vld1q_f32(w3 + j),      x0);
            a31 = vfmaq_f32(a31, vld1q_f32(w3 + j + 4),  x1);
            a32 = vfmaq_f32(a32, vld1q_f32(w3 + j + 8),  x2);
            a33 = vfmaq_f32(a33, vld1q_f32(w3 + j + 12), x3);
        }

        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            a00 = vfmaq_f32(a00, vld1q_f32(w0 + j), xv);
            a10 = vfmaq_f32(a10, vld1q_f32(w1 + j), xv);
            a20 = vfmaq_f32(a20, vld1q_f32(w2 + j), xv);
            a30 = vfmaq_f32(a30, vld1q_f32(w3 + j), xv);
        }

        float32x4_t s0 = vaddq_f32(vaddq_f32(a00, a01), vaddq_f32(a02, a03));
        float32x4_t s1 = vaddq_f32(vaddq_f32(a10, a11), vaddq_f32(a12, a13));
        float32x4_t s2 = vaddq_f32(vaddq_f32(a20, a21), vaddq_f32(a22, a23));
        float32x4_t s3 = vaddq_f32(vaddq_f32(a30, a31), vaddq_f32(a32, a33));
        float v0 = vaddvq_f32(s0);
        float v1 = vaddvq_f32(s1);
        float v2 = vaddvq_f32(s2);
        float v3 = vaddvq_f32(s3);

        for (; j < n; j++) {
            float xj = x[j];
            v0 += w0[j] * xj;
            v1 += w1[j] * xj;
            v2 += w2[j] * xj;
            v3 += w3[j] * xj;
        }

        xout[i + 0] = v0;
        xout[i + 1] = v1;
        xout[i + 2] = v2;
        xout[i + 3] = v3;
    }

    for (int i = d4; i < d; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.f);
        float32x4_t a1 = vdupq_n_f32(0.f);
        float32x4_t a2 = vdupq_n_f32(0.f);
        float32x4_t a3 = vdupq_n_f32(0.f);

        int j = 0;
        for (; j < n16; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        }
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

#include <arm_neon.h>
#include <stdint.h>
#include <dispatch/dispatch.h>

static inline void mm_block2(float* xout, const float* x, const float* w, int n, int start, int end) {
    const int n16 = n & ~15;
    int i = start;
    // Process two rows at a time: load x once, reuse for both rows (8 FMA chains).
    for (; i + 1 < end; i += 2) {
        const float* w0 = w + (size_t)i * (size_t)n;
        const float* w1 = w + (size_t)(i + 1) * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
        float32x4_t b0 = vdupq_n_f32(0.0f), b1 = vdupq_n_f32(0.0f);
        float32x4_t b2 = vdupq_n_f32(0.0f), b3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n16; j += 16) {
            float32x4_t x0 = vld1q_f32(x + j);
            float32x4_t x1 = vld1q_f32(x + j + 4);
            float32x4_t x2 = vld1q_f32(x + j + 8);
            float32x4_t x3 = vld1q_f32(x + j + 12);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j),      x0);
            a1 = vfmaq_f32(a1, vld1q_f32(w0 + j + 4),  x1);
            a2 = vfmaq_f32(a2, vld1q_f32(w0 + j + 8),  x2);
            a3 = vfmaq_f32(a3, vld1q_f32(w0 + j + 12), x3);
            b0 = vfmaq_f32(b0, vld1q_f32(w1 + j),      x0);
            b1 = vfmaq_f32(b1, vld1q_f32(w1 + j + 4),  x1);
            b2 = vfmaq_f32(b2, vld1q_f32(w1 + j + 8),  x2);
            b3 = vfmaq_f32(b3, vld1q_f32(w1 + j + 12), x3);
        }
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            a0 = vfmaq_f32(a0, vld1q_f32(w0 + j), xv);
            b0 = vfmaq_f32(b0, vld1q_f32(w1 + j), xv);
        }
        float32x4_t sa = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float32x4_t sb = vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3));
        float va = vaddvq_f32(sa);
        float vb = vaddvq_f32(sb);
        for (; j < n; j++) {
            float xv = x[j];
            va += w0[j] * xv;
            vb += w1[j] * xv;
        }
        xout[i]     = va;
        xout[i + 1] = vb;
    }
    // Tail row if odd count.
    if (i < end) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
        float32x4_t a2 = vdupq_n_f32(0.0f), a3 = vdupq_n_f32(0.0f);
        int j = 0;
        for (; j < n16; j += 16) {
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j),      vld1q_f32(x + j));
            a1 = vfmaq_f32(a1, vld1q_f32(wp + j + 4),  vld1q_f32(x + j + 4));
            a2 = vfmaq_f32(a2, vld1q_f32(wp + j + 8),  vld1q_f32(x + j + 8));
            a3 = vfmaq_f32(a3, vld1q_f32(wp + j + 12), vld1q_f32(x + j + 12));
        }
        for (; j + 4 <= n; j += 4)
            a0 = vfmaq_f32(a0, vld1q_f32(wp + j), vld1q_f32(x + j));
        float32x4_t s = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float val = vaddvq_f32(s);
        for (; j < n; j++) val += wp[j] * x[j];
        xout[i] = val;
    }
}

typedef struct { float* xout; float* x; float* w; int n; int d; int start; int end; } mm_arg;

void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;
    // Chunk rows; keep chunk even so two-row pairing stays aligned within tasks.
    int chunk = 16;
    while (chunk < d && (d + chunk - 1) / chunk > 96) chunk *= 2;
    chunk &= ~1;
    if (chunk < 2) chunk = 2;
    int nchunks = (d + chunk - 1) / chunk;
    if (nchunks > 128) nchunks = 128;

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t k) {
        int start = (int)k * chunk;
        int end = start + chunk;
        if (end > d) end = d;
        if (start < d) mm_block2(xout, x, w, n, start, end);
    });
}

