// Process 4 rows at a time, reusing x loads across rows.
static inline void mm_block(float* xout, float* x, float* w, int n, int d, int start, int end) {
    const int n16 = n & ~15;
    int i = start;
    for (; i + 4 <= end; i += 4) {
        const float* w0 = w + (size_t)i * (size_t)n;
        const float* w1 = w0 + n;
        const float* w2 = w1 + n;
        const float* w3 = w2 + n;
