        float32x4_t s1 = vaddq_f32(vaddq_f32(a10, a11), vaddq_f32(a12, a13));
        float32x4_t s2 = vaddq_f32(vaddq_f32(a20, a21), vaddq_f32(a22, a23));
        float32x4_t s3 = vaddq_f32(vaddq_f32(a30, a31), vaddq_f32(a32, a33));
        float v0 = vaddvq_f32(s0);
        float v1 = vaddvq_f32(s1);
        float v2 = vaddvq_f32(s2);
        float v3 = vaddvq_f32(s3);
        for (; j + 4 <= n; j += 4) {
            float32x4_t xv = vld1q_f32(x + j);
            v0 += vaddvq_f32(vmulq_f32(vld1q_f32(w0 + j), xv));
            v1 += vaddvq_f32(vmulq_f32(vld1q_f32(w1 + j), xv));
            v2 += vaddvq_f32(vmulq_f32(vld1q_f32(w2 + j), xv));
            v3 += vaddvq_f32(vmulq_f32(vld1q_f32(w3 + j), xv));
        }
        for (; j < n; j++) {
            float xv = x[j];
            v0 += w0[j] * xv;
            v1 += w1[j] * xv;
            v2 += w2[j] * xv;
            v3 += w3[j] * xv;
        }
        xout[i]     = v0;
        xout[i + 1] = v1;
        xout[i + 2] = v2;
        xout[i + 3] = v3;
    }
    // Tail rows
    for (; i < end; i++) {
        const float* wp = w + (size_t)i * (size_t)n;
        float32x4_t a0 = vdupq_n_f32(0.0f), a1 = vdupq_n_f32(0.0f);
