    mm_arg args[128];
    if (nchunks > 128) nchunks = 128;

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t k) {
        int start = (int)k * chunk;
        int end = start + chunk;
        if (end > d) end = d;
        if (start < d) mm_block(xout, x, w, n, d, start, end);
    });
}

