            v1 += vaddvq_f32(vmulq_f32(vld1q_f32(wp1 + j), xv));
            v2 += vaddvq_f32(vmulq_f32(vld1q_f32(wp2 + j), xv));
            v3 += vaddvq_f32(vmulq_f32(vld1q_f32(wp3 + j), xv));
