void matmul(float* xout, float* x, float* w, int n, int d) {
    if (d <= 0) return;

    int chunk = 16;
    while (chunk < d && (d + chunk - 1) / chunk > 96) chunk *= 2;
    chunk = (chunk + 3) & ~3;  // keep chunks a multiple of 4 rows for the main kernel
    int nchunks = (d + chunk - 1) / chunk;
    if (nchunks < 1) nchunks = 1;
    if (nchunks > 128) nchunks = 128;

    mm_arg args[128];
    for (int k = 0; k < nchunks; k++) {
        int start = k * chunk;
        int end = start + chunk;
        if (end > d) end = d;
        args[k].xout = xout; args[k].x = x; args[k].w = w;
        args[k].n = n; args[k].d = d;
        args[k].start = start; args[k].end = end;
    }

    dispatch_apply(nchunks, DISPATCH_APPLY_AUTO, ^(size_t k) {
        mm_arg* a = &args[k];
        if (a->start < a->end) mm_block(a->xout, a->x, a->w, a->n, a->d, a->start, a->end);
    });
}

