            c3 = vfmaq_f32(c3, vld1q_f32(wp2 + j + 12), x3);

            e0 = vfmaq_f32(e0, vld1q_f32(wp3 + j),      x0);
            e1 = vfmaq_f32(e1, vld1q_f32(wp3 + j + 4),  x1);
            e2 = vfmaq_f32(e2, vld1q_f32(wp3 + j + 8),  x2);
            e3 = vfmaq_f32(e3, vld1q_f32(wp3 + j + 12), x3);
        }

        float32x4_t s0 = vaddq_f32(vaddq_f32(a0, a1), vaddq_f32(a2, a3));
        float32x4_t s1 = vaddq_f32(vaddq_f32(b0, b1), vaddq_f32(b2, b3));
        float32x4_t s2 = vaddq_f32(vaddq_f32(c0, c1), vaddq_f32(c2, c3));
        float32x4_t s3 = vaddq_f32(vaddq_f32(e0, e1), vaddq_f32(e2, e3));
        float v0 = vaddvq_f32(s0);
        float v1 = vaddvq_f32(s1);
        float v2 = vaddvq_f32(s2);
        float v3 = vaddvq_f32(s3);

        for (; j < n; j++) {
            const float xj = x[j];
            v0 += wp0[j] * xj;
            v1 += wp1[j] * xj;
            v2 += wp2[j] * xj;
            v3 += wp3[j] * xj;
        }
        xout[i]     = v0;
        xout[i + 1] = v1;
        xout[i + 2] = v2;
        xout[i + 3] = v3;
